<?php require_once __DIR__.'/includes/functions.php'; $orders=[]; if($_SERVER['REQUEST_METHOD']==='POST'){ check_csrf(); $st=db()->prepare('SELECT * FROM orders WHERE phone=? ORDER BY id DESC LIMIT 5'); $st->execute([$_POST['phone']]); $orders=$st->fetchAll(); if(!$orders) flash('error','لم نعثر على طلبات مسجلة بهذا الرقم.'); } $title='تتبّع الطلب | ALAN'; include __DIR__.'/includes/header.php'; ?><div class="page"><div class="tracking"><div class="page-title"><p class="eyebrow">طلباتكِ</p><h1>تتبّع طلبكِ</h1></div><form class="form-card" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><p style="margin-bottom:15px; font-size:14px; color:var(--ink-light)">أدخلي رقم الهاتف المستخدم أثناء الطلب لعرض آخر طلباتك وحالتها.</p><label>رقم الهاتف</label><input name="phone" required placeholder="0550 000 000"><button class="btn" style="margin-top:15px">عرض الطلبات</button></form><?php if($orders): $statuses=['received'=>'تم الاستلام','confirmed'=>'مؤكد','preparing'=>'جاري التحضير','shipped'=>'تم الشحن','out_for_delivery'=>'في الطريق','delivered'=>'مستلم','cancelled'=>'ملغى','rejected'=>'مرفوض']; foreach($orders as $o): $keys=array_keys($statuses); $current=array_search($o['status'],$keys); ?><div class="form-card" style="margin-top:20px;"><h3>الطلب <?=e($o['order_number'])?> <span style="float:left; font-size:14px; color:var(--brand); text-align:left; line-height:1.2;"><?=money($o['total'])?><?php if(!empty($o['promo_code'])): ?><br><small style="color:var(--ink-light); font-size:11px;">(خصم <?=$o['promo_code']?>)</small><?php endif; ?></span></h3><p style="margin-bottom:15px; font-size:13px; color:var(--ink-light)"><?=e($o['created_at'])?></p><div class="timeline" style="margin-top:0; padding:15px; background:var(--bg); border-radius:8px;"><?php foreach(['received','confirmed','shipped','delivered'] as $k): $v=$statuses[$k]; $isPast = $current >= array_search($k, $keys); ?><div class="<?=!$isPast?'muted':''?>"><strong><?=$v?></strong></div><?php endforeach;?></div><?php if(in_array($o['status'], ['cancelled','rejected'])): ?><div style="color:red; margin-top:10px; font-weight:bold;">حالة الطلب: <?=e($statuses[$o['status']])?></div><?php endif; ?></div><?php endforeach; endif; ?></div></div><?php include __DIR__.'/includes/footer.php';?>
